cd "$(pwd)" && node --input-type=module -e "
import { uniqueStrings } from './unique_changed.mjs';

// Basic dedup preserving order and first occurrence
const a = ['apple', 'banana', 'apple', 'cherry', 'banana'];
const r1 = uniqueStrings(a);
console.log('r1:', JSON.stringify(r1));
console.assert(JSON.stringify(r1) === JSON.stringify(['apple','banana','cherry']), 'r1 failed');

// Case-insensitive dedup, original spelling preserved
const b = ['Hello', 'hello', 'HELLO', 'World', 'world'];
const r2 = uniqueStrings(b);
console.log('r2:', JSON.stringify(r2));
console.assert(JSON.stringify(r2) === JSON.stringify(['Hello','World']), 'r2 failed');

// Whitespace not trimmed
const c = ['  x', 'x', '  x'];
const r3 = uniqueStrings(c);
console.log('r3:', JSON.stringify(r3));
console.assert(JSON.stringify(r3) === JSON.stringify(['  x','x']), 'r3 failed');

// Input not mutated
const d = ['a', 'A', 'b'];
const snapshot = JSON.stringify(d);
uniqueStrings(d);
console.assert(JSON.stringify(d) === snapshot, 'input mutated');

// Empty array
console.assert(JSON.stringify(uniqueStrings([])) === '[]', 'empty failed');

// Mixed case with distinct keys
const e = ['Foo', 'foo', 'bar', 'BAR', 'baz'];
const r5 = uniqueStrings(e);
console.log('r5:', JSON.stringify(r5));
console.assert(JSON.stringify(r5) === JSON.stringify(['Foo','bar','baz']), 'r5 failed');

console.log('All checks passed.');
"

